
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_m05_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_m05", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.003846988023888e+00, -2.909479879093303e+00, -2.781487886815197e+00, -2.616373374876747e+00, -2.422941361281434e+00, -2.233113167477875e+00, -2.081591474220536e+00, -1.893266873687597e+00, -1.522953300823177e+00, -1.234311372912748e+00, -8.840211219342416e-01, -5.535668799986188e-01, -4.332553088494891e-01, -3.613220330229422e-01, -2.694460342070659e-01, -2.004430508180093e-01, -1.425733606160057e-01, -1.845943342271935e-02, -8.229508867668177e-04, -7.169923886001685e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


